INSERT INTO `wp_comments` VALUES (1,1,'A WordPress Commenter','wapuu@wordpress.example','https://wordpress.org/','','2026-07-17 15:24:14','2026-07-17 15:24:14','Hi, this is a comment.\nTo get started with moderating, editing, and deleting comments, please visit the Comments screen in the dashboard.\nCommenter avatars come from <a href=\"https://gravatar.com/\">Gravatar</a>.',0,'trash','','comment',0,0),(2,40,'','','','','2026-07-17 19:56:50','2026-07-17 19:56:50','Payment created with status \"Pending\".',0,'1','','payment_note',0,1),(3,40,'','','','','2026-07-17 19:56:54','2026-07-17 19:56:54','Payment status changed from \"Pending\" to \"Completed\".',0,'1','','payment_note',0,1);
