INSERT INTO `wp_pmpro_membership_levels` VALUES (1,'Starter','Free articles, selected lessons, community updates, and learning progress.','Welcome to CodesBlock. Your free member account is ready.',0.00000000,0.00000000,0,'',0,0.00000000,0,1,0,''),(2,'Pro Monthly Pass','Thirty days of every paid course, implementation resources, certificates, and saved progress. Renew only when you want to continue.','Your 30-day CodesBlock Pro pass is active. Every paid course is unlocked.',999.00000000,0.00000000,0,'',0,0.00000000,0,1,1,'Month'),(3,'Lifetime','Permanent access to all current and future CodesBlock courses.','Lifetime access is active. Welcome to the inner circle.',19999.00000000,0.00000000,0,'',0,0.00000000,0,1,0,''),(4,'Pro Annual Pass','A full year of every paid course, implementation resources, certificates, and saved progress. One payment, no auto-renewal.','Your one-year CodesBlock Pro pass is active.',8499.00000000,0.00000000,0,'',0,0.00000000,0,1,1,'Year');
